('advanced-native-918', '["phrase"]'::jsonb, '{"advanced-native-918-v1-audio":{"type":"mc","answers":["She gave firm orders and closed off discussion of alternatives."],"options":["She confirmed that every participant willingly agreed with the timetable.","She gave firm orders and closed off discussion of alternatives.","She invited suggestions and compared them before choosing.","The chair recorded a timetable the group had already agreed after comparing alternatives."]},"advanced-native-918-v2-reply":{"type":"mc","answers":["She insisted on her timetable without hearing another option.","She laid down the law instead of discussing why the plan was failing.","Her response made the schedule compulsory rather than opening a comparison.","She told everyone what to do and ruled out alternatives."],"options":["She insisted on her timetable without hearing another option.","She laid down the law instead of discussing why the plan was failing.","Her response made the schedule compulsory rather than opening a comparison.","She told everyone what to do and ruled out alternatives."]},"advanced-native-918-v1-scene":{"type":"mc","answers":["The manager laid down the law about the handover format."],"options":["The manager laid down the law about the handover format.","The manager invited everyone to choose an independent format immediately.","The statement alone proves that every staff member agreed with the format."]},"advanced-native-918-v1-contrast":{"type":"mc","answers":["The person necessarily created a legally binding statute."],"options":["More context is needed to judge whether that firmness was appropriate.","The person gave firm instructions about what others should do.","The person necessarily created a legally binding statute."]},"advanced-native-918-v1-branch":{"type":"mc","answers":["She laid down the law, but giving an order does not tell us whether the group agreed."],"options":["She laid down the law, but giving an order does not tell us whether the group agr